/** Type mirror for the injected JavaScript module; keep synchronized with script.js. */
export interface YouTubeTranscriptArguments {
  language?: string;
  format?: 'segments' | 'text';
}

/**
 * Expected failures are reported in `error`, never as a rejection: WebMCP collapses every
 * callback rejection to a bare UnknownError. Only abort rejects.
 */
export interface YouTubeTranscriptResult {
  /** Null only when the page offered no video data; see `error`. */
  metadata: null | {
    videoId: string;
    title: string;
    author: string;
    channelId: string;
    lengthSeconds: number;
    viewCount: number;
    description: string;
    keywords: string[];
    isLive: boolean;
  };
  transcript: null | {
    language: string;
    languageName: string;
    isAutoGenerated: boolean;
    segmentCount: number;
    text?: string;
    segments?: Array<{ start: number; duration: number; text: string }>;
  };
  /**
   * Degradations on a successful read, e.g. YouTube's transcript panel loaded a different
   * caption track than the one selected; `transcript.language` reflects the loaded track.
   */
  warnings?: string[];
  error?: string;
}

export interface YouTubeTranscriptExecutionOptions {
  signal?: AbortSignal;
}

export function execute(
  args?: YouTubeTranscriptArguments,
  options?: YouTubeTranscriptExecutionOptions
): Promise<YouTubeTranscriptResult>;
